def fix_bugs(n, m, s, a, b, c):
    students = sorted(range(n), key=lambda x: -c[x])
    bugs = sorted(range(m), key=lambda x: a[x])
    schedule = [-1] * m
    passes_given = [0] * n

    for bug in bugs:
        for student in students:
            if b[student] >= a[bug] and passes_given[student] < c[student]:
                schedule[bug] = student + 1
                passes_given[student] += 1
                break

    if sum(passes_given) > s:
        return "NO"

    return "YES\n" + " ".join(map(str, schedule))

