import sys
from typing import List

def assign_students(n: int, m: int, s: int, a: List[int], b: List[int], c: List[int]) -> bool:
    def can_assign(students: List[int]) -> bool:
        used_passes = [0] * len(c)
        assigned_bugs = [False] * m
        day = 0

        while not all(assigned_bugs):
            new_day = True
            for student in range(n):
                if students[student] > 0 and not assigned_bugs[b[student]-1]:
                    if used_passes[students[student]-1] + 1 <= c[student]:
                        assigned_bugs[b[student]-1] = True
                        used_passes[students[student]-1] += 1
                        students[student] -= 1
                        new_day = False

            if new_day:
                day += 1

        return sum(used_passes) <= s

    for k in range(m+1):
        if can_assign(b[:k]):
            return True, [b[i] for i in range(k)]

    return False, []

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    s = int(data[2])

    a = list(map(int, data[3:3+m]))
    b = list(map(int, data[3+m:3+m+n]))
    c = list(map(int, data[3+m+n:]))

    result, assignment = assign_students(n, m, s, a, b, c)

